using System.Globalization;
using System.Numerics;
using API.Interfaces;
using API.Interfaces.JSON_Objects.Tables;
using API.Problems.NPComplete.NPC_RSA;
using API.Problems.NPComplete.NPC_RSA.Solvers;
using API.Problems.NPComplete.NPC_RSA.Verifiers;
using API.Problems.NPComplete.NPC_RSA.Visualizations;
using Xunit;

namespace redux_tests;

#pragma warning disable CS1591

/// <summary>
/// RSA problem tests. Known answers come from the Encryption Lesson's worked example (N = 55, e = 3, d = 27:
/// the message 13 encrypts to 52), from keys generated by the thesis Phase 0 reference implementation (itself
/// checked against NIST data), and from NIST ACVP SP 800-56B RSA decryption-primitive vectors. Expected
/// message-mode ciphertexts were computed independently (A = 1 ... Z = 26, space = 27).
/// </summary>
public class RSA_Tests {

    private const string Lesson = "(55,3,52)";

    // "HELLO WORLD" under the lesson key: each letter's code cubed mod 55.
    private static readonly int[] HelloWorldCiphertexts = { 17, 15, 23, 23, 20, 48, 12, 20, 2, 23, 9 };

    // --- Instance parsing ---

    [Fact]
    public void RSA_Default_Instance_Is_A_Message_Under_The_Lesson_Key() {
        var problem = new RSA();
        Assert.Equal("(55,3,\"Hello World\")", problem.instance);
        Assert.True(problem.isMessage);
        Assert.Equal(new BigInteger(55), problem.modulus);
        Assert.Equal(new BigInteger(3), problem.publicExponent);
        Assert.Equal(HelloWorldCiphertexts.Select(c => new BigInteger(c)), problem.ciphertexts);
    }

    [Fact]
    public void RSA_Number_Instance_Is_The_Lesson_Example() {
        var problem = new RSA(Lesson);
        Assert.False(problem.isMessage);
        Assert.Equal(new BigInteger(52), Assert.Single(problem.ciphertexts));
        Assert.Equal(new BigInteger(52), BigInteger.ModPow(13, 3, 55)); // the lesson's message 13, encrypted
    }

    [Theory]
    [InlineData("(55,3,\"hello world\")")]
    [InlineData("( 55 , 3 , \"HELLO WORLD\" )")]
    public void RSA_Message_Ignores_Case_And_Spacing_Around_Values(string instance) {
        Assert.Equal(new RSA().ciphertexts, new RSA(instance).ciphertexts);
    }

    [Theory]
    [InlineData("")]
    [InlineData("(55,3)")]
    [InlineData("55,3,52")]
    [InlineData("(55,x,52)")]
    [InlineData("(2,1,0)")]                 // N < 3
    [InlineData("(55,1,52)")]               // e <= 1
    [InlineData("(55,55,52)")]              // e >= N
    [InlineData("(55,3,55)")]               // c >= N
    [InlineData("(55,3,-1)")]               // c < 0
    [InlineData("(55,3,\"\")")]             // empty message
    [InlineData("(55,3,\"HI)")]             // unclosed quote
    [InlineData("(55,3,\"H1\")")]           // digit in the message
    [InlineData("(55,3,\"HI, YOU\")")]      // punctuation in the message
    [InlineData("(15,7,\"HI\")")]           // N too small for letter codes up to 27
    public void RSA_Rejects_Malformed_Or_Out_Of_Range_Instances(string instance) {
        Assert.Throws<ProblemParseException>(() => new RSA(instance));
    }

    // --- Factoring attack ---

    [Fact]
    public void FactoringAttack_Recovers_The_Lesson_Key_Step_By_Step() {
        var problem = new RSA(Lesson);
        var solver = new RSAFactoringAttackSolver();

        Assert.Equal("13", solver.solve(problem));

        var steps = solver.GetSteps(problem).Cast<RSAStep>().ToList();
        Assert.Equal(RSAStep.Secrets, steps.Select(s => s.Variable));
        Assert.Equal(new[] { "5", "11", "40", "27", "13" }, steps.Select(s => s.Value));
        Assert.Contains("4 tries", steps[0].HowFound); // 55 is divisible by 5 after trying 2, 3, 4 and 5
    }

    [Fact]
    public void FactoringAttack_Recovers_The_Default_Message() {
        var problem = new RSA();
        var solver = new RSAFactoringAttackSolver();

        Assert.Equal("HELLO WORLD", solver.solve(problem));

        var steps = solver.GetSteps(problem).Cast<RSAStep>().ToList();
        Assert.Equal(4 + 11, steps.Count); // p, q, phi, d, then one step per letter
        var letters = steps.Skip(4).ToList();
        Assert.Equal(Enumerable.Range(0, 11).Select(i => (int?)i), letters.Select(s => s.Letter));
        Assert.Equal(new[] { "8", "5", "12", "12", "15", "27", "23", "15", "18", "12", "4" }, letters.Select(s => s.Value));
        Assert.Contains("which is space", letters[5].HowFound);
    }

    // N, e, c, p, q, phi, d, m: keys from the thesis Phase 0 reference implementation, each with the first
    // character of a test message as m. p is the smaller prime, the one trial division finds first.
    [Theory]
    [InlineData("323", "5", "21", "17", "19", "288", "173", "72")]
    [InlineData("3233", "7", "1317", "53", "61", "3120", "1783", "65")]
    [InlineData("8633", "5", "1970", "89", "97", "8448", "5069", "77")]
    [InlineData("11413", "3", "6443", "101", "113", "11200", "7467", "81")]
    [InlineData("988027", "7", "425677", "991", "997", "986040", "140863", "82")]
    [InlineData("10062757", "5", "4502656", "1009", "9973", "10051776", "8041421", "83")]
    [InlineData("1000609937", "7", "47003677", "10007", "99991", "1000499940", "142928563", "84")]
    [InlineData("9998000099", "13", "1698654563", "99989", "99991", "9997800120", "7690615477", "84")]
    public void Both_Solvers_Recover_Phase0_Reference_Keys(
        string n, string e, string c, string p, string q, string phi, string d, string m) {
        var problem = new RSA($"({n},{e},{c})");

        var attack = new RSAFactoringAttackSolver();
        Assert.Equal(m, attack.solve(problem));
        Assert.Equal(new[] { p, q, phi, d, m }, attack.GetSteps(problem).Cast<RSAStep>().Select(s => s.Value));

        Assert.Equal(m, new RSAPlaintextSearchSolver().solve(problem));
        Assert.True(new RSAVerifier().verify(problem, m));
    }

    [Fact]
    public void Message_Mode_Shows_That_A_Always_Encrypts_To_1() {
        // 1^e = 1, so every A in the message is visible in the ciphertext under any key.
        var problem = new RSA("(3233,7,\"Attack at dawn\")");
        Assert.Equal(new BigInteger[] { 1, 339, 339, 1, 2187, 1880, 1101, 1, 339, 1101, 219, 1, 1196, 1539 }, problem.ciphertexts);
        Assert.Equal("ATTACK AT DAWN", new RSAFactoringAttackSolver().solve(problem));
        Assert.Equal("ATTACK AT DAWN", new RSAPlaintextSearchSolver().solve(problem));
    }

    [Theory]
    [InlineData("(53,3,1)", "is prime")]                                // N prime
    [InlineData("(49,5,3)", "not a product of two distinct primes")]   // N = 7 * 7
    [InlineData("(30,7,1)", "not a product of two distinct primes")]   // N = 2 * 3 * 5
    [InlineData("(55,5,2)", "has no inverse")]                          // gcd(5, phi = 40) = 5
    public void FactoringAttack_Reports_Keys_That_Are_Not_Valid_RSA(string instance, string reason) {
        string answer = new RSAFactoringAttackSolver().solve(new RSA(instance));
        Assert.StartsWith("No solution", answer);
        Assert.Contains(reason, answer);
    }

    [Fact]
    public void FactoringAttack_Stops_When_The_Timer_Expires() {
        var solver = new RSAFactoringAttackSolver { timerHasExpired = true };
        Assert.Equal(RSAFactoringAttackSolver.Timeout, solver.solve(new RSA()));
    }

    // --- Plaintext search ---

    [Fact]
    public void PlaintextSearch_Finds_The_Lesson_Message_Without_Learning_The_Key() {
        var solver = new RSAPlaintextSearchSolver();
        Assert.Equal("13", solver.solve(new RSA(Lesson)));

        var step = Assert.Single(solver.GetSteps(new RSA(Lesson)).Cast<RSAStep>());
        Assert.Equal(RSAStep.M, step.Variable);
        Assert.Equal("13", step.Value);
        Assert.Contains("14 tries", step.HowFound); // m = 0 through 13, as in the lesson
    }

    [Fact]
    public void PlaintextSearch_Recognises_Repeated_Letters() {
        var solver = new RSAPlaintextSearchSolver();
        Assert.Equal("HELLO WORLD", solver.solve(new RSA()));

        var steps = solver.GetSteps(new RSA()).Cast<RSAStep>().ToList();
        Assert.Equal(11, steps.Count);
        Assert.All(steps, s => Assert.Equal(RSAStep.M, s.Variable));
        // The second L (letter 4) repeats letter 3's ciphertext, so it needs no search.
        Assert.Contains("already appeared as letter 3", steps[3].HowFound);
        Assert.DoesNotContain("already appeared", steps[2].HowFound);
    }

    [Fact]
    public void PlaintextSearch_Stops_When_The_Timer_Expires() {
        var solver = new RSAPlaintextSearchSolver { timerHasExpired = true };
        Assert.Equal(RSAPlaintextSearchSolver.Timeout, solver.solve(new RSA()));
    }

    // --- Verifier ---

    [Theory]
    [InlineData("13", true)]
    [InlineData(" 13 ", true)]
    [InlineData("12", false)]
    [InlineData("68", false)]  // 68 = 13 + 55 encrypts to 52 too, but is not below N
    [InlineData("-3", false)]
    public void Verifier_Accepts_Only_The_Number(string certificate, bool expected) {
        Assert.Equal(expected, new RSAVerifier().verify(new RSA(Lesson), certificate));
    }

    [Theory]
    [InlineData("HELLO WORLD", true)]
    [InlineData("hello world", true)]
    [InlineData("\"Hello World\"", true)]
    [InlineData("HELLO WORLE", false)]
    [InlineData("HELLO", false)]
    [InlineData("HELLO WORLDS", false)]
    public void Verifier_Accepts_Only_The_Message(string certificate, bool expected) {
        Assert.Equal(expected, new RSAVerifier().verify(new RSA(), certificate));
    }

    [Fact]
    public void Verifier_Accepts_The_Advertised_Example_For_The_Default_Instance() {
        Assert.True(new RSAVerifier().verify(new RSA(), RSAVerifier.CertificateExample));
    }

    [Theory]
    [InlineData(Lesson, "thirteen")]
    [InlineData("(55,3,\"Hello World\")", "HELL0 WORLD")]
    public void Verifier_Rejects_A_Certificate_It_Cannot_Read(string instance, string certificate) {
        Assert.Throws<CertificateParseException>(() => new RSAVerifier().verify(new RSA(instance), certificate));
    }

    // NIST ACVP RSA decryption-primitive vectors (SP 800-56B Rev. 2): modulus, public exponent, plaintext and
    // ciphertext in hex. Solving at these sizes is infeasible, but verifying is one modular exponentiation.
    [Theory]
    [InlineData(1, "", "02DE387DD9", "", "")] // 2048-bit
    [InlineData(47, "", "3262454CF1B221", "", "")] // 2048-bit
    [InlineData(90, "", "1BB0345DC9", "", "")] // 4096-bit
    public void Verifier_Checks_NIST_Vectors(int testCaseId, string nHex, string eHex, string ptHex, string ctHex) {
        BigInteger n = FromHex(nHex), e = FromHex(eHex), pt = FromHex(ptHex), ct = FromHex(ctHex);
        var problem = new RSA($"({n},{e},{ct})");

        Assert.True(new RSAVerifier().verify(problem, pt.ToString()), $"NIST tcId {testCaseId}");
        Assert.False(new RSAVerifier().verify(problem, (pt + 1).ToString()), $"NIST tcId {testCaseId}");
    }

    private static BigInteger FromHex(string hex) =>
        BigInteger.Parse("0" + hex, NumberStyles.HexNumber, CultureInfo.InvariantCulture);

    // --- Visualization ---

    private static List<API_TableJSON> Frames(RSA problem, ISolver solver) =>
        new RSAKnowledgeTableVisualization()
            .StepsVisualization(problem, solver.GetSteps(problem.instance))
            .Cast<API_TableJSON>().ToList();

    private static TableRow Row(API_TableJSON table, string id) => table.rows.Single(r => r.id == id);

    [Fact]
    public void Visualization_Starts_With_Only_The_Public_Values_Known() {
        var table = new RSAKnowledgeTableVisualization().visualize(new RSA(Lesson));

        Assert.Equal(new[] { "N", "e", "c", "p", "q", "phi", "d", "m" }, table.rows.Select(r => r.id));
        Assert.Equal("55", Row(table, "N").cells["value"]);
        Assert.Equal("52", Row(table, "c").cells["value"]);
        Assert.All(RSAStep.Secrets, secret => Assert.Equal("?", Row(table, secret).cells["value"]));
        Assert.All(table.rows, row => Assert.Null(row.color));
    }

    [Fact]
    public void Visualization_Fills_In_One_Secret_Per_Factoring_Step() {
        var frames = Frames(new RSA(Lesson), new RSAFactoringAttackSolver());
        Assert.Equal(5, frames.Count);

        // Frame 3 (phi found): p and q filled in, phi highlighted as the newest row, d and m still unknown.
        var third = frames[2];
        Assert.Equal("11", Row(third, "q").cells["value"]);
        Assert.Equal("40", Row(third, "phi").cells["value"]);
        Assert.Equal("ElementHighlight", Row(third, "phi").color);
        Assert.Null(Row(third, "q").color);
        Assert.Equal("?", Row(third, "d").cells["value"]);

        // Last frame: the plaintext found and marked as the solution.
        var last = frames[^1];
        Assert.Equal("13", Row(last, "m").cells["value"]);
        Assert.Equal("Solution", Row(last, "m").color);
    }

    [Fact]
    public void Visualization_Builds_The_Message_Letter_By_Letter() {
        var problem = new RSA();
        var frames = Frames(problem, new RSAFactoringAttackSolver());
        Assert.Equal(4 + 11, frames.Count);

        Assert.Equal("17, 15, 23, 23, 20, 48, 12, 20, 2, 23, 9", Row(frames[0], "c").cells["value"]);

        // After the third letter: H, E and L decoded, the rest still unknown, and not yet the solution.
        var third = frames[4 + 2];
        Assert.Equal("8, 5, 12, ?, ?, ?, ?, ?, ?, ?, ? = \"HEL????????\"", Row(third, "m").cells["value"]);
        Assert.Equal("ElementHighlight", Row(third, "m").color);
        Assert.Equal("Step 7 of 15: found letter 3 of 11", third.title);

        var last = frames[^1];
        Assert.Equal("8, 5, 12, 12, 15, 27, 23, 15, 18, 12, 4 = \"HELLO WORLD\"", Row(last, "m").cells["value"]);
        Assert.Equal("Solution", Row(last, "m").color);
    }

    [Fact]
    public void Visualization_Shows_That_Plaintext_Search_Never_Learns_The_Key() {
        var frames = Frames(new RSA(), new RSAPlaintextSearchSolver());
        Assert.Equal(11, frames.Count);
        Assert.Contains("HELLO WORLD", Row(frames[^1], "m").cells["value"]);
        Assert.All(new[] { "p", "q", "phi", "d" }, secret => Assert.Equal("?", Row(frames[^1], secret).cells["value"]));
    }
}
